from pathlib import Path
P=Path(__file__).resolve().parent;R=P.parents[2]
read=lambda p:json.loads(p.read_text())
manifest=read(R/'agent-artifacts/manifests/v2.2.2/production_manifest_masterplan_v2_2_2.json');rows={r['plannedId']:r for r in manifest['manifest'] if r['batch']=='Batch 03'};skeletons=read(P/'decision-skeletons.json');assert len(skeletons)==25
cases=[]
def op(text,q,reason,temptation,when):return dict(text=text,decisionQuality=q,isBest=q==1,reasoningPattern='context-bound-decision' if q==1 else 'incomplete-tradeoff',failurePattern=None if q==1 else 'decisive-fact-missed',explanation=reason,whyTempting=temptation,whyNotBest='Ограничение не применимо: '+reason if q==1 else reason,whenItWouldBeBest=when)
def add(n,title,context,question,options,facts,insight,model,source,level):
 id=f'TC-{n:03}';r=rows[id];c={k:copy.deepcopy(r[k]) for k in ['partId','topicId','domain','requiredLevel','primaryPattern','secondaryPatterns','scenarioFamilyId','trainingEligible','assessmentEligible']};c.update(id=id,revision=1,type='single-best',title=title,sourceTopicExplanation=source,context=context,question=question,options=[dict(o,id=chr(65+i)) for i,o in enumerate(options)],decisiveFacts=facts,keyInsight=insight,mentalModel=model,decisiveMutation=r['decisiveMutationConcept'],authorRationale=level);cases.append(c)
# F-DR-T01: identical strategy wording, only L changes in context.
base='Вы — delivery manager сервиса. Помимо обязательных quality/security gates действует дополнительное ручное ревью. Его цена с трудом и задержкой поставки — 6 условных единиц в месяц; одна единица равна 100 тыс. ₽. Готовая автоматическая проверка стоит 2 единицы и сохраняет половину предотвращаемой ручным ревью денежной потери. Её эффект проверен; переход бесплатен. Удаление только дополнительного шага ничего не стоит. Обязательные gates при любом решении сохраняются. Категория риска и цена отдельного дефекта постоянны; остаточный риск всех трёх режимов допустим. Сопоставимое исследование с контролем иных изменений уже установило эффект; ещё одно исследование обойдётся в единицу, новых условий в ближайший месяц не ожидается. Предотвращаемая ручным ревью потеря за месяц — '
texts=['Заменить дополнительное ревью готовой автоматической проверкой; сохранить обязательные gates и отслеживать остаточные потери на общем горизонте.','Оставить дополнительное ревью ещё на месяц; оплатить повторное исследование и выбрать постоянный режим по двум измерениям.','Удалить дополнительное ревью из процесса; оставить обязательные gates и наблюдать дефекты без отдельного дополнительного шага.','Сохранить дополнительное ручное ревью; учитывать его труд и задержки при ежемесячном сопоставлении предотвращённых потерь и затрат.']
whens=['Когда частичная автоматическая защита даёт больший чистый эффект, чем ручная, а её остаточный риск допустим.','Когда исходная оценка ненадёжна, ожидаемая ценность новых данных оправдывает исследование и временное сохранение ручного шага.','Когда дополнительный шаг не окупает свою цену, а обязательная защита и допустимость остаточного риска сохраняются.','Когда дополнительная польза ручной защиты превышает её добавочную цену относительно доступной автоматизации.']
for n,L,key,qs in [(76,0,'C',[.7,.45,1,.5]),(77,6,'A',[1,.6,.75,.75]),(78,18,'D',[.76,.88,.3,1])]:
 nets=[.5*L-2,L-7,0,L-6];reasons=[f'Автоматическая защита предотвращает {L/2:g} единиц потерь при цене 2; чистый эффект {nets[0]:g}. '+('Это максимум среди доступных режимов.' if key=='A' else f'Выбранный режим {key} даёт больший чистый эффект.'),f'Повторное исследование сохраняет текущий режим и добавляет единицу расходов. Надёжность исходной оценки уже подтверждена, а новых условий нет; отсрочка не покупает полезную информацию.',f'Дополнительные расходы и защита исчезают: чистый эффект 0. '+('При нулевой доказанной пользе платить за дополнительный шаг незачем.' if key=='C' else f'Это хуже доступного режима {key}, который даёт положительный чистый эффект.'),f'Ручная защита предотвращает {L} единиц при цене 6; чистый эффект {nets[3]:g}. '+('Её добавочная защита окупает разницу стоимости с автоматизацией.' if key=='D' else 'Максимум защиты не означает максимум полезного эффекта после затрат.')]
 add(n,'Цена дополнительного ревью',base+str(L)+' единиц.','Какой режим дополнительной проверки выбрать?', [op(texts[i],qs[i],reasons[i],['Автоматизация дешевле ручного труда.','Второе измерение кажется защитой от поспешной оптимизации.','Удаление шага сокращает ожидание и затраты.','Ручной шаг сохраняет весь наблюдаемый эффект.'][i],whens[i]) for i in range(4)], [f'Доказанная предотвращаемая потеря ручного шага — {L} единиц в месяц.','Ручной шаг стоит 6; автоматический — 2 и сохраняет половину эффекта; переход бесплатен.','Обязательные gates остаются, риски допустимы, достоверность оценки уже проверена.'],'Полезность проверки нужно сравнивать с её полной ценой и доступной альтернативой.','Для необязательного контроля сравните предотвращённый ущерб за один горизонт с трудом и задержкой; больше защиты не всегда означает лучший процесс.','§3.2 требует доказанной связи gate с качеством, измерения его эффекта и удаления бесполезных проверок; ручные и автоматические шаги имеют разную цену.','Middle: сравнить три допустимых режима по полной стоимости и потерянной защите. Семейные границы L=4 и L=8; единственное изменение — L.')
